problem usa2022_p4 (p q : ℕ) :
    (p, q) ∈ solution_set ↔
    p.Prime ∧ q.Prime ∧
    ∃ a, a^2 + q = p ∧ ∃ b, b^2 + q = p * q  := by
  constructor
  intro hpq;
  obtain ⟨rfl, rfl⟩ := hpq;
  exact ⟨by norm_num, by norm_num, 1, by norm_num, 2, by norm_num⟩

  rintro ⟨hpp, hpq, a, ha, b, hb⟩;
  have hq_pos : 0 < q := Nat.Prime.pos hpq;
  have hq_lep : q ≤ p := (Nat.le_add_left q (a ^ 2)).trans_eq ha;
  have hba' : 0 < b - a := Nat.sub_pos_of_lt (Nat.le_lt_asymm hq_lep (Nat.mul_lt_mul_left (Nat.Prime.pos hpp) (q.le_p_iff.mp hpq)).mp hb);
  exact ⟨by decode := true, hqpos := hq_pos, hb a b (Nat.mul_le_mul_right_iff_left' zero_lt_two.le _)⟩
